function DraggableCard({task,openTask,onDrop,onLayout,blocked}){
 const pan=React.useRef(new Animated.ValueXY()).current;
 const [dragging,setDragging]=useState(false);
 const responder=useMemo(()=>PanResponder.create({
  onStartShouldSetPanResponder:()=>true,
  onMoveShouldSetPanResponder:()=>true,
  onPanResponderGrant:()=>{pan.setValue({x:0,y:0});setDragging(true)},
  onPanResponderMove:(_,g)=>pan.setValue({x:g.dx,y:g.dy}),
  onPanResponderTerminationRequest:()=>false,
  onPanResponderRelease:(_,g)=>{pan.setValue({x:0,y:0});setDragging(false);if(Math.abs(g.dx)+Math.abs(g.dy)>9)onDrop(task.id,g.moveX,g.moveY)},
  onPanResponderTerminate:()=>{pan.setValue({x:0,y:0});setDragging(false)}
 }),[task.id,onDrop,pan]);
 return <Animated.View onLayout={onLayout} style={{transform:pan.getTranslateTransform(),zIndex:dragging?100:0,opacity:dragging?.85:1}}>
  <TaskCard task={task} onPress={()=>openTask(task.id)} grabProps={responder.panHandlers} blocked={blocked}/>
 </Animated.View>;
}
function Board({project,tasks,openTask,onMove,compact=false}){
 const lanes=React.useRef({}),layouts=React.useRef({});
 const drop=useCallback((taskId,x,y)=>{
  if(!Number.isFinite(x)||!Number.isFinite(y))return;
  STATUSES.forEach(status=>{
   const ref=lanes.current[status];if(!ref||!ref.measureInWindow)return;
   ref.measureInWindow((lx,ly,lw,lh)=>{
    if(x<lx||x>lx+lw||y<ly||y>ly+lh)return;
    const list=tasks.filter(t=>t.status===status&&t.id!==taskId).sort((a,b)=>a.position-b.position);
    const localY=y-ly;let index=list.length;
    for(let i=0;i<list.length;i++){
     const r=layouts.current[list[i].id];if(r&&localY<r.y+r.height/2){index=i;break}
    }
    onMove(taskId,status,index);
   });
  });
 },[tasks,onMove]);
 return <View>
  <Txt color={C.muted} size={11} style={{marginBottom:10}}>Grab the purple handle to move a card across lanes or reorder it. Open a card to change status without dragging.</Txt>
  <ScrollView horizontal showsHorizontalScrollIndicator contentContainerStyle={{paddingBottom:14,gap:12}}>
   {STATUSES.map(status=>{const list=tasks.filter(t=>t.status===status).sort((a,b)=>a.position-b.position);
    return <View ref={r=>{lanes.current[status]=r}} key={status} style={{width:compact?248:278,minHeight:270,backgroundColor:C.side,borderColor:C.border,borderWidth:1,borderRadius:12,padding:10}}>
     <View style={{flexDirection:'row',alignItems:'center',justifyContent:'space-between',marginBottom:12,paddingHorizontal:4}}>
      <View style={{flexDirection:'row',alignItems:'center',gap:8}}><View style={{height:7,width:7,borderRadius:6,backgroundColor:laneColors[status]}}/><Txt size={12} bold>{status}</Txt></View>
      <Chip label={String(list.length)} small color={C.sub}/>
     </View>
     {list.map(t=><DraggableCard key={t.id} task={t} openTask={openTask} blocked={model.blockers(project,t).length>0}
      onDrop={drop} onLayout={e=>{layouts.current[t.id]=e.nativeEvent.layout}}/>)}
    </View>;
   })}
  </ScrollView>
 </View>;
}
function Timeline({project,openTask,onShift,onSchedule}){
 const [range,setRange]=useState(30),[windowShift,setWindowShift]=useState(0);
 const scheduled=project.tasks.filter(t=>t.start||t.due).slice().sort((a,b)=>(a.start||a.due).localeCompare(b.start||b.due));
 const unscheduled=project.tasks.filter(t=>!t.start&&!t.due);
 const today=new Date().toISOString().slice(0,10);
 const first=scheduled.length?scheduled.map(t=>t.start||t.due).sort()[0]:today;
 const anchor=first<today?first:today;
 const start=model.shiftDate(anchor,windowShift);
 const dayWidth=27,labelWidth=184;
 const dates=Array.from({length:range},(_,i)=>model.shiftDate(start,i));
 const dateOffset=(date)=>Math.round((Date.parse(date+'T00:00:00Z')-Date.parse(start+'T00:00:00Z'))/86400000);
 return <View>
  <View style={{flexDirection:'row',alignItems:'center',flexWrap:'wrap',gap:7,marginBottom:14}}>
   <Txt color={C.sub} size={12}>Timeline scale</Txt>
   {[14,30,90].map(days=><Btn key={days} label={`${days} days`} compact tone={days===range?'primary':'neutral'} onPress={()=>setRange(days)}/>)}
   <Chip label={`${scheduled.length} scheduled`} color={C.cyan}/><Btn label="Previous" compact icon="chevron-back" onPress={()=>setWindowShift(v=>v-range)}/><Btn label="Beginning" compact onPress={()=>setWindowShift(0)}/><Btn label="Next" compact icon="chevron-forward" onPress={()=>setWindowShift(v=>v+range)}/><Txt size={11} color={C.muted}>{start} → {model.shiftDate(start,range-1)}</Txt>
  </View>
  <Box style={{padding:12}}>
   <ScrollView horizontal contentContainerStyle={{minWidth:labelWidth+range*dayWidth}}>
    <View>
     <View style={{flexDirection:'row',paddingBottom:8,borderBottomWidth:1,borderBottomColor:C.border}}>
      <View style={{width:labelWidth}}><Txt size={11} color={C.sub}>TASK / DAYS</Txt></View>
      {dates.map((date,i)=><View key={date} style={{width:dayWidth,alignItems:'center',borderLeftWidth:1,borderLeftColor:C.border}}><Txt size={9} color={date===today?C.purple:C.muted}>{i===0||date.endsWith('-01')?date.slice(5):date.slice(8)}</Txt></View>)}
     </View>
     {scheduled.map(task=>{
      const from=task.start||task.due,end=task.due&&task.due>=from?task.due:from;
      const offset=dateOffset(from),duration=Math.max(1,dateOffset(end)-offset+1);
      const visibleStart=Math.max(0,offset),visibleEnd=Math.min(range,offset+duration);
      const blocked=model.blockers(project,task).length>0;
      return <View key={task.id} style={{flexDirection:'row',minHeight:51,borderBottomWidth:1,borderBottomColor:C.border}}>
       <View style={{width:labelWidth,justifyContent:'center',paddingRight:7}}><Pressable onPress={()=>openTask(task.id)}><Txt size={11} bold lines={1}>{task.title}</Txt></Pressable><View style={{flexDirection:'row',alignItems:'center',gap:10}}>
        <Pressable accessibilityLabel={`Move ${task.title} one day earlier`} onPress={()=>onShift(task.id,-1)}><I name="chevron-back-circle-outline" size={18} color={C.cyan}/></Pressable>
        <Pressable accessibilityLabel={`Move ${task.title} one day later`} onPress={()=>onShift(task.id,1)}><I name="chevron-forward-circle-outline" size={18} color={C.cyan}/></Pressable>
        {blocked&&<I name="lock-closed-outline" size={12} color={C.amber}/>}</View>
       </View>
       <View style={{width:range*dayWidth,minHeight:49,justifyContent:'center'}}>
        <View style={{position:'absolute',flexDirection:'row',top:0,bottom:0}}>{dates.map(date=><View key={date} style={{width:dayWidth,borderLeftWidth:1,borderLeftColor:date===today?C.purpleDim:C.border}}/>)}</View>
        {visibleEnd>visibleStart&&<Pressable onPress={()=>openTask(task.id)} accessibilityLabel={`Edit timeline for ${task.title}`} style={{position:'absolute',left:visibleStart*dayWidth+2,width:Math.max(12,(visibleEnd-visibleStart)*dayWidth-4),height:23,borderRadius:6,backgroundColor:blocked?C.amber:task.status==='Done'?C.green:C.purple,opacity:.86,justifyContent:'center',paddingHorizontal:5}}><Txt size={9} color={C.bg} bold lines={1}>{task.id}</Txt></Pressable>}
       </View>
      </View>;
     })}
    </View>
   </ScrollView>
  </Box>
  {!!unscheduled.length&&<Box style={{padding:15,marginTop:12}}><Txt size={13} bold>Unscheduled tasks ({unscheduled.length})</Txt><Txt color={C.muted} size={11} style={{marginVertical:8}}>Give tasks start and due dates to place them on the timeline.</Txt>
   {unscheduled.map(t=><View key={t.id} style={{flexDirection:'row',alignItems:'center',justifyContent:'space-between',gap:8,paddingVertical:6}}><Pressable onPress={()=>openTask(t.id)} style={{flex:1}}><Txt size={12} lines={1}>{t.title}</Txt></Pressable><Btn compact label="Schedule" onPress={()=>onSchedule(t.id)}/></View>)}
  </Box>}
 </View>;
}
function Empty({icon='folder-open-outline',title='Nothing here yet',desc,action}){return <View style={{alignItems:'center',padding:35,gap:10}}><I name={icon} size={29}/><Txt size={15} bold>{title}</Txt><Txt size={12} color={C.muted} style={{textAlign:'center'}}>{desc}</Txt>{action}</View>}

