 const addAttachment=()=>{if(!edit)return;const url=attachmentDraft.url.trim();if(!/^https?:\/\//i.test(url)){notify('Attachment needs an http:// or https:// URL');return;}updateTask({...edit,attachments:[...edit.attachments,{id:id('attachment'),name:attachmentDraft.name.trim()||url,url}]},`Linked attachment to ${edit.id}`);setAttachmentDraft({name:'',url:''})};
